+                FirebaseApp.initializeApp(options);
+                System.out.println("Firebase Admin SDK başarıyla başlatıldı!");
+            }
+        } catch (Exception e) {
+            e.printStackTrace();
+            System.err.println("Firebase başlatılırken bir hata oluştu: " + e.getMessage());
+        }
+    }
+}
